INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('rev1', 'rest_la_quercia', 'usr_guest', 5, 'The entrance is modest, while the dining room opens into a bright courtyard. Bread and water were replenished before the peppery peposo reached the table. A quiet table should be requested in advance rather than assumed.', '[]', '2025-08-04T00:00:00Z');
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('rev2', 'rest_fico_duomo', 'usr_foodie', 4.1, 'We arrived before the dinner rush and were seated beside the front window.
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('rev3', 'rest_campo_centro', 'usr_trip', 5, 'We booked the first evening sitting, which made conversation easy. Bread and water were replenished before the lemon semifreddo reached the table. One practical note: booking directly produced a clearer confirmation than the third-party listing.', '[]', '2025-08-06T00:00:00Z');
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('retehhplia', 'mesp3llbex', 'usw225ybns', 3.3, 'Our group split several starters before choosing individual main courses. First impression — we preferred the texture of the pappardelle al cinghiale to the richer special ordered by the next table. Taxi pickup worked best from the next corner because the lane is pedestrian-only at night.', '[]', '2025-08-07T00:00:00Z');
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('retsd73idu', 'mesp3llbex', 'usw77ypvoo', 4.4, 'Our table was ready at the booked time, despite a busy Friday service. The ribollita came in two smaller courses, useful for sharing across the table. The meal ended on schedule, leaving ample time for the last tram.', '[]', '2025-08-08T00:00:00Z');
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('rewfnsroxn', 'mesp3llbex', 'ustgyzpkqp', 5, 'After walking from the station, we stopped here without a long wait.
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('redg7npdqr', 'mewus5m4fx', 'usw225ybns', 4.6, 'We chose a weekday evening and heard more local diners than tour groups. The seasonal vegetable tart was the strongest plate, especially the restrained use of salt. One practical note: reservations appear sensible on weekends; several walk-ins were turned away.', '[]', '2025-08-11T00:00:00Z');
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('re2slurl3s', 'mewus5m4fx', 'usw77ypvoo', 5, 'After walking from the station, we stopped here without a long wait. First impression — bread and water were replenished before the seasonal vegetable tart reached the table. Taxi pickup worked best from the next corner because the lane is pedestrian-only at night.', '[]', '2025-08-12T00:00:00Z');
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('reufdqmgyo', 'mewus5m4fx', 'ustgyzpkqp', 3.8, 'Our group split several starters before choosing individual main courses. A suggested local wine paired neatly with the ribollita and was available by the glass. Our server changed at shift handoff, but the allergy note was repeated accurately.', '[]', '2025-08-13T00:00:00Z');
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('rehe2akj6d', 'me3yiwmcca', 'usw225ybns', 5, 'Rain pushed everyone indoors; staff reorganized the tables without delaying orders.
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('rerytz5fiq', 'me3yiwmcca', 'usw77ypvoo', 3.1, 'We came for a family dinner and found the pace relaxed rather than formal. The braised beef cheek was the strongest plate, especially the restrained use of salt. One practical note: reservations appear sensible on weekends; several walk-ins were turned away.', '[]', '2025-08-16T00:00:00Z');
INSERT INTO "reviews" ("review_id", "merchant_id", "user_id", "rating", "body", "image_captions", "created_at") VALUES ('readvetmgw', 'me3yiwmcca', 'ustgyzpkqp', 4.2, 'The kitchen was finishing lunch service when we arrived, yet nothing felt rushed. First impression — the pumpkin ravioli needed a few more minutes, so the kitchen sent a small vegetable course first. We would return for lunch, when the room is reportedly less crowded.', '[]', '2025-08-17T00:00:00Z');
